#!/usr/bin/env python3
import argparse
import csv
import hashlib
import json
import sys
from pathlib import Path

SEED_DATA = [
    ('I love this product, it is amazing and works great', 'positive'),
    ('Excellent quality, highly recommend', 'positive'),
    ('This is the best purchase I have made', 'positive'),
    ('Very happy with this, good value', 'positive'),
    ('Great experience, would buy again', 'positive'),
    ('Terrible product, broke after one day', 'negative'),
    ('Worst purchase ever, do not buy', 'negative'),
    ('Very disappointed, poor quality', 'negative'),
    ('I hate this, it is useless', 'negative'),
    ('Bad experience, would not recommend', 'negative'),
]

def compute_sha256(path):
    h = hashlib.sha256()
    with open(path, 'rb') as f:
        for chunk in iter(lambda: f.read(65536), b''):
            h.update(chunk)
    return h.hexdigest()

def load_rows(path):
    p = Path(path)
    rows = []
    if p.suffix.lower() == '.csv':
        with open(p, 'r', encoding='utf-8', newline='') as f:
            reader = csv.DictReader(f)
            for row in reader:
                rows.append(dict(row))
    else:
        with open(p, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line:
                    continue
                rows.append(json.loads(line))
    return rows

def get_input_text(row):
    for key in ('review', 'Review', 'REVIEW', 'text', 'Text', 'TEXT'):
        if key in row and row[key] is not None:
            return str(row[key])
    for k, v in row.items():
        if k in ('label', 'Label', 'LABEL', 'target', 'Target', '__benchmark_id'):
            continue
        if isinstance(v, str):
            return v
    return ''

def get_target(row):
    for key in ('label', 'Label', 'LABEL', 'target', 'Target'):
        if key in row and row[key] is not None:
            return str(row[key])
    return None

def get_id(row):
    if '__benchmark_id' in row and row['__benchmark_id'] is not None:
        return str(row['__benchmark_id'])
    return None

def extract_prediction(result):
    if isinstance(result, str):
        return result
    if isinstance(result, dict):
        if not result:
            return None
        return max(result.items(), key=lambda kv: kv[1])[0]
    if isinstance(result, (list, tuple)):
        if not result:
            return None
        first = result[0]
        if isinstance(first, (list, tuple)):
            return first[0]
        return first
    return str(result)

def build_tokenizer():
    from naiveBayesClassifier import tokenizer
    return tokenizer.Tokenizer(stop_words=[], signs_to_remove=['?!#%&'])

def train_classifier(train_rows):
    from naiveBayesClassifier.trainer import Trainer
    from naiveBayesClassifier.classifier import Classifier
    tok = build_tokenizer()
    trainer = Trainer(tok)
    for row in train_rows:
        text = get_input_text(row)
        target = get_target(row)
        if target is None:
            continue
        trainer.train(text, target)
    return Classifier(trainer.data, build_tokenizer())

def predict_with_seed():
    seed_rows = [{'review': t, 'label': c} for t, c in SEED_DATA]
    return train_classifier(seed_rows)

def compute_metrics(y_true, y_pred):
    if not y_true:
        return {}
    total = len(y_true)
    correct = sum(1 for t, p in zip(y_true, y_pred) if t == p)
    accuracy = correct / total if total else 0.0
    classes = sorted(set(y_true))
    f1s = []
    for c in classes:
        tp = sum(1 for t, p in zip(y_true, y_pred) if t == c and p == c)
        fp = sum(1 for t, p in zip(y_true, y_pred) if t != c and p == c)
        fn = sum(1 for t, p in zip(y_true, y_pred) if t == c and p != c)
        precision = tp / (tp + fp) if (tp + fp) > 0 else 0.0
        recall = tp / (tp + fn) if (tp + fn) > 0 else 0.0
        f1 = 2 * precision * recall / (precision + recall) if (precision + recall) > 0 else 0.0
        f1s.append(f1)
    macro_f1 = sum(f1s) / len(f1s) if f1s else 0.0
    return {'accuracy': accuracy, 'macro_f1': macro_f1}

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--dataset', required=True)
    parser.add_argument('--output-dir', required=True)
    parser.add_argument('--limit', type=int, default=None)
    parser.add_argument('--repo-root', required=True)
    parser.add_argument('--seed', type=int, default=0)
    args = parser.parse_args()

    repo_root = str(Path(args.repo_root).resolve())
    if repo_root not in sys.path:
        sys.path.insert(0, repo_root)

    out_dir = Path(args.output_dir)
    out_dir.mkdir(parents=True, exist_ok=True)

    dataset_sha256 = compute_sha256(args.dataset)
    rows = load_rows(args.dataset)
    if args.limit is not None:
        if args.limit < 0:
            raise ValueError('--limit must be non-negative')
        rows = rows[:args.limit]

    has_target = any(get_target(r) is not None for r in rows)
    labeled_rows = [r for r in rows if get_target(r) is not None]

    predictions = []
    y_true = []
    y_pred = []

    if has_target and labeled_rows:
        for idx, row in enumerate(rows):
            text = get_input_text(row)
            true_label = get_target(row)
            if true_label is not None:
                train_rows = [r for r in labeled_rows if r is not row]
                if not train_rows:
                    train_rows = labeled_rows
                clf = train_classifier(train_rows)
                result = clf.classify(text)
                pred = extract_prediction(result)
                if pred is None:
                    pred = 'unknown'
                pred_obj = {'prediction': pred, 'target': true_label}
                id_val = get_id(row)
                if id_val is not None:
                    pred_obj['id'] = id_val
                predictions.append(pred_obj)
                y_true.append(true_label)
                y_pred.append(pred)
            else:
                clf = train_classifier(labeled_rows)
                result = clf.classify(text)
                pred = extract_prediction(result)
                if pred is None:
                    pred = 'unknown'
                pred_obj = {'prediction': pred}
                id_val = get_id(row)
                if id_val is not None:
                    pred_obj['id'] = id_val
                predictions.append(pred_obj)
    else:
        clf = predict_with_seed()
        for idx, row in enumerate(rows):
            text = get_input_text(row)
            result = clf.classify(text)
            pred = extract_prediction(result)
            if pred is None:
                pred = 'unknown'
            pred_obj = {'prediction': pred}
            id_val = get_id(row)
            if id_val is not None:
                pred_obj['id'] = id_val
            predictions.append(pred_obj)

    metrics = compute_metrics(y_true, y_pred) if y_true else {}

    with open(out_dir / 'predictions.jsonl', 'w', encoding='utf-8') as f:
        for obj in predictions:
            f.write(json.dumps(obj, ensure_ascii=False) + '\n')

    with open(out_dir / 'metrics.json', 'w', encoding='utf-8') as f:
        json.dump(metrics, f, ensure_ascii=False, indent=2)

    manifest = {
        'status': 'success',
        'dataset_sha256': dataset_sha256,
        'sample_count': len(predictions),
        'seed': args.seed,
        'adapter': 'naiveBayesClassifier_import_wrapper',
    }
    with open(out_dir / 'run_manifest.json', 'w', encoding='utf-8') as f:
        json.dump(manifest, f, ensure_ascii=False, indent=2)

    summary = {
        'status': 'success',
        'sample_count': len(predictions),
        'metrics': metrics,
        'dataset_sha256': dataset_sha256,
    }
    print(json.dumps(summary, ensure_ascii=False))

if __name__ == '__main__':
    main()

